Here's a complete game in one file. Save it as `cat-game.html` and open it in any browser to play.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Cat Fish Catcher</title>
<style>
  html, body { margin:0; height:100%; background:#1b2a49; overflow:hidden; touch-action:none; }
  body { display:flex; align-items:center; justify-content:center; }
  canvas { background:linear-gradient(#87ceeb, #e0f4ff); border-radius:12px; }
</style>
</head>
<body>
<canvas id="game" width="480" height="640"></canvas>
<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = canvas.width, H = canvas.height;

// Fit canvas to the window while keeping aspect ratio
function resize() {
  const scale = Math.min(window.innerWidth / W, window.innerHeight / H);
  canvas.style.width = (W * scale) + 'px';
  canvas.style.height = (H * scale) + 'px';
}
window.addEventListener('resize', resize);
resize();

let state = 'start';           // start | play | over
let cat, items, score, lives, spawnTimer, flash, popups, clouds;
let best = 0;
try { best = parseInt(localStorage.getItem('catFishBest')) || 0; } catch (e) {}

const keys = {};
let targetX = null;

clouds = Array.from({length: 4}, () => ({
  x: Math.random() * W, y: 40 + Math.random() * 200, s: 0.2 + Math.random() * 0.3
}));

function reset() {
  cat = { x: W / 2, y: H - 70, facing: 1 };
  items = [];
  popups = [];
  score = 0;
  lives = 5;
  spawnTimer = 0;
  flash = 0;
  targetX = null;
}

function spawn() {
  const r = Math.random();
  let type;
  if (r < 0.65) type = { emoji: '🐟', points: 1, good: true };
  else if (r < 0.80) type = { emoji: '🐠', points: 3, good: true };
  else type = { emoji: '👢', points: 0, good: false };
  items.push({
    x: 30 + Math.random() * (W - 60),
    y: -30,
    vy: 2 + Math.random() * 1.5 + Math.min(score * 0.04, 4) + (type.points === 3 ? 1 : 0),
    rot: Math.random() * 6,
    spin: (Math.random() - 0.5) * 0.1,
    ...type
  });
}

function addPopup(x, y, text, color) {
  popups.push({ x, y, text, color, life: 40 });
}

function update(dt) {
  // Clouds drift
  clouds.forEach(c => { c.x += c.s * dt; if (c.x > W + 60) c.x = -60; });
  if (state !== 'play') return;

  // Movement: keyboard or pointer
  const speed = 8 * dt;
  if (keys['ArrowLeft'] || keys['a'] || keys['A']) { cat.x -= speed; cat.facing = -1; targetX = null; }
  if (keys['ArrowRight'] || keys['d'] || keys['D']) { cat.x += speed; cat.facing = 1; targetX = null; }
  if (targetX !== null) {
    const dx = targetX - cat.x;
    if (Math.abs(dx) > 2) cat.facing = dx > 0 ? 1 : -1;
    cat.x += dx * Math.min(1, 0.25 * dt);
  }
  cat.x = Math.max(35, Math.min(W - 35, cat.x));

  // Spawning (gets faster as score rises)
  spawnTimer -= dt;
  if (spawnTimer <= 0) {
    spawn();
    spawnTimer = Math.max(22, 65 - score * 1.2);
  }

  // Items
  for (let i = items.length - 1; i >= 0; i--) {
    const it = items[i];
    it.y += it.vy * dt;
    it.rot += it.spin * dt;

    // Caught?
    if (Math.abs(it.x - cat.x) < 45 && it.y > cat.y - 45 && it.y < cat.y + 10) {
      if (it.good) {
        score += it.points;
        addPopup(it.x, it.y, '+' + it.points, '#1e8e3e');
      } else {
        lives--;
        flash = 15;
        addPopup(it.x, it.y, 'Ew, a boot!', '#d93025');
      }
      items.splice(i, 1);
      continue;
    }

    // Hit the ground
    if (it.y > H - 20) {
      if (it.good) {
        lives--;
        flash = 15;
        addPopup(it.x, H - 50, 'Missed!', '#d93025');
      }
      items.splice(i, 1);
    }
  }

  // Popups
  popups.forEach(p => { p.y -= 0.8 * dt; p.life -= dt; });
  popups = popups.filter(p => p.life > 0);
  if (flash > 0) flash -= dt;

  if (lives <= 0) {
    state = 'over';
    if (score > best) {
      best = score;
      try { localStorage.setItem('catFishBest', best); } catch (e) {}
    }
  }
}

function text(str, x, y, size, color = '#fff', align = 'center') {
  ctx.font = `bold ${size}px system-ui, sans-serif`;
  ctx.textAlign = align;
  ctx.textBaseline = 'middle';
  ctx.fillStyle = color;
  ctx.fillText(str, x, y);
}

function emoji(e, x, y, size, rot = 0, flip = 1) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.scale(flip, 1);
  ctx.font = `${size}px serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(e, 0, 0);
  ctx.restore();
}

function draw() {
  ctx.clearRect(0, 0, W, H);

  // Clouds
  clouds.forEach(c => emoji('☁️', c.x, c.y, 60));

  // Ground
  ctx.fillStyle = '#7bc96f';
  ctx.fillRect(0, H - 30, W, 30);
  ctx.fillStyle = '#5fae55';
  ctx.fillRect(0, H - 30, W, 6);

  if (state === 'start') {
    emoji('🐱', W / 2, 250, 110);
    text('Cat Fish Catcher', W / 2, 160, 38, '#1b2a49');
    text('Catch the fish falling from the sky!', W / 2, 340, 18, '#1b2a49');
    text('🐟 = 1 pt   🐠 = 3 pts   👢 = ouch!', W / 2, 375, 18, '#1b2a49');
    text('Move: ← → keys, A / D, or mouse / finger', W / 2, 420, 16, '#35507a');
    text('Tap or press Space to start', W / 2, 500, 22, '#e8710a');
    if (best) text('Best: ' + best, W / 2, 545, 18, '#1b2a49');
    return;
  }

  // Items
  items.forEach(it => emoji(it.emoji, it.x, it.y, 40, it.rot));

  // Cat (flips to face the direction it's moving)
  emoji('🐱', cat.x, cat.y, 64, 0, cat.facing);

  // Popups
  popups.forEach(p => {
    ctx.globalAlpha = Math.min(1, p.life / 20);
    text(p.text, p.x, p.y, 20, p.color);
    ctx.globalAlpha = 1;
  });

  // HUD
  text('Score: ' + score, 14, 24, 22, '#1b2a49', 'left');
  text('❤️'.repeat(Math.max(0, lives)), W - 14, 24, 20, '#000', 'right');
  text('Best: ' + best, 14, 52, 14, '#35

