You don't need to know any coding, though. It's just copy, paste, and double-click:

1. **Copy** everything in the box below.
2. **Open Notepad** (Windows) or **TextEdit** (Mac, then click Format → Make Plain Text) and paste it in.
3. **Save it** with the name `cat-game.html`. On Windows, set "Save as type" to "All Files". Put it somewhere easy, like your Desktop.
4. **Double-click** the file and it opens in your browser. Move the cat with your mouse, finger, or the arrow keys.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Cat Fish Catcher</title>
<style>
  html, body { margin:0; height:100%; background:#1b2a49; overflow:hidden; touch-action:none; }
  body { display:flex; align-items:center; justify-content:center; }
  canvas { background:linear-gradient(#87ceeb, #e0f4ff); border-radius:12px; }
</style>
</head>
<body>
<canvas id="game" width="480" height="640"></canvas>
<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = 480, H = 640;

function resize() {
  const s = Math.min(innerWidth / W, innerHeight / H);
  canvas.style.width = W * s + 'px';
  canvas.style.height = H * s + 'px';
}
addEventListener('resize', resize);
resize();

let state = 'start', cat, items, score, lives, timer, popups, best = 0;
const keys = {};
let targetX = null;

function reset() {
  cat = { x: W / 2, y: H - 70, facing: 1 };
  items = []; popups = [];
  score = 0; lives = 5; timer = 0; targetX = null;
}
reset();

function spawn() {
  const r = Math.random();
  const t = r < 0.65 ? { e: '🐟', p: 1, good: true }
          : r < 0.8  ? { e: '🐠', p: 3, good: true }
          :            { e: '👢', p: 0, good: false };
  items.push({ ...t, x: 30 + Math.random() * (W - 60), y: -30,
    vy: 2 + Math.random() * 1.5 + Math.min(score * 0.04, 4) });
}

function popup(x, y, txt, color) { popups.push({ x, y, txt, color, life: 40 }); }

function update(dt) {
  if (state !== 'play') return;
  if (keys['ArrowLeft'] || keys['a']) { cat.x -= 8 * dt; cat.facing = -1; targetX = null; }
  if (keys['ArrowRight'] || keys['d']) { cat.x += 8 * dt; cat.facing = 1; targetX = null; }
  if (targetX !== null) {
    const dx = targetX - cat.x;
    if (Math.abs(dx) > 2) cat.facing = dx > 0 ? 1 : -1;
    cat.x += dx * Math.min(1, 0.25 * dt);
  }
  cat.x = Math.max(35, Math.min(W - 35, cat.x));

  timer -= dt;
  if (timer <= 0) { spawn(); timer = Math.max(22, 65 - score * 1.2); }

  for (let i = items.length - 1; i >= 0; i--) {
    const it = items[i];
    it.y += it.vy * dt;
    if (Math.abs(it.x - cat.x) < 45 && it.y > cat.y - 45 && it.y < cat.y + 10) {
      if (it.good) { score += it.p; popup(it.x, it.y, '+' + it.p, '#1e8e3e'); }
      else { lives--; popup(it.x, it.y, 'Ew, a boot!', '#d93025'); }
      items.splice(i, 1);
    } else if (it.y > H - 20) {
      if (it.good) { lives--; popup(it.x, H - 50, 'Missed!', '#d93025'); }
      items.splice(i, 1);
    }
  }
  popups.forEach(p => { p.y -= 0.8 * dt; p.life -= dt; });
  popups = popups.filter(p => p.life > 0);

  if (lives <= 0) { state = 'over'; best = Math.max(best, score); }
}

function text(s, x, y, size, color, align = 'center') {
  ctx.font = `bold ${size}px system-ui, sans-serif`;
  ctx.textAlign = align; ctx.textBaseline = 'middle';
  ctx.fillStyle = color;
  ctx.fillText(s, x, y);
}

function emoji(e, x, y, size, flip = 1) {
  ctx.save();
  ctx.translate(x, y); ctx.scale(flip, 1);
  ctx.font = size + 'px serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(e, 0, 0);
  ctx.restore();
}

function draw() {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#7bc96f'; ctx.fillRect(0, H - 30, W, 30);
  ctx.fillStyle = '#5fae55'; ctx.fillRect(0, H - 30, W, 6);

  if (state === 'start') {
    text('Cat Fish Catcher', W / 2, 160, 38, '#1b2a49');
    emoji('🐱', W / 2, 250, 110);
    text('Catch the fish falling from the sky!', W / 2, 340, 18, '#1b2a49');
    text('🐟 = 1 pt    🐠 = 3 pts    👢 = ouch!', W / 2, 375, 18, '#1b2a49');
    text('Move with mouse, finger, or arrow keys', W / 2, 420, 16, '#35507a');
    text('Tap or press Space to start', W / 2, 500, 22, '#e8710a');
    return;
  }

  items.forEach(it => emoji(it.e, it.x, it.y, 40));
  emoji('🐱', cat.x, cat.y, 64, cat.facing);
  popups.forEach(p => {
    ctx.globalAlpha = Math.min(1, p.life / 20);
    text(p.txt, p.x, p.y, 20, p.color);
    ctx.globalAlpha = 1;
  });
  text('Score: ' + score, 14, 24, 22, '#1b2a49', 'left');
  text('Best: ' + best, 14, 52, 14, '#35507a', 'left');
  text('❤️'.repeat(Math.max(0, lives)), W - 14, 24, 20, '#000', 'right');

  if (state === 'over') {
    ctx.fillStyle = 'rgba(27,42,73,0.75)'; ctx.fillRect(0, 0, W, H);
    text('Game Over', W / 2, 250, 44, '#fff');
    text('Score: ' + score, W / 2, 310, 26, '#ffd54f');
    text('Tap or press Space to play again', W / 2, 380, 20, '#fff');
  }
}

let last = performance.now();
function loop(now) {
  const dt = Math.min(2, (now - last) / 16.67);
  last = now;
  update(dt); draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

function startOrRestart() {
  if (state !== 'play') { reset(); state = 'play'; }
}
addEventListener('keydown', e => {
  keys[e.key] = true;
  if (e.key === ' ') startOrRestart();
});
addEventListener('keyup', e => keys[e.key] = false);

function pointerX(e) {
  const rect = canvas.getBoundingClientRect();
  return (e.clientX - rect.left) * (W / rect.width);
}
canvas.addEventListener('pointerdown', e => { startOrRestart(); targetX = pointerX(e); });
canvas.addEventListener('pointermove', e => { if (state === 'play') targetX = pointerX(e); });
</script>
</body>
</html>
```

