Glad it worked, and 14 points is a good first try! Here's the updated game with an orange cat and golden fish worth 100 points. They're rare and fall fast, and missing one doesn't cost you a life.

Do the same steps as before: copy all of this, go back to the w3schools page, select everything in the code box, paste over it, and tap **Run »**.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Cat Fish Catcher</title>
<style>
  html, body { margin:0; height:100%; background:#1b2a49; overflow:hidden; touch-action:none; }
  body { display:flex; align-items:center; justify-content:center; }
  canvas { background:linear-gradient(#87ceeb, #e0f4ff); border-radius:12px; }
</style>
</head>
<body>
<canvas id="game" width="480" height="640"></canvas>
<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = 480, H = 640;

function resize() {
  const s = Math.min(innerWidth / W, innerHeight / H);
  canvas.style.width = W * s + 'px';
  canvas.style.height = H * s + 'px';
}
addEventListener('resize', resize);
resize();

let state = 'start', cat, items, score, lives, timer, popups, best = 0, tick = 0;
const keys = {};
let targetX = null;

function reset() {
  cat = { x: W / 2, y: H - 70, facing: 1 };
  items = []; popups = [];
  score = 0; lives = 5; timer = 0; targetX = null;
}
reset();

function spawn() {
  const r = Math.random();
  const level = Math.min(score, 40);
  let t;
  if (r < 0.04)      t = { kind: 'gold', p: 100, good: true, free: true };
  else if (r < 0.58) t = { kind: 'fish', e: '🐟', p: 1, good: true };
  else if (r < 0.75) t = { kind: 'fish', e: '🐠', p: 3, good: true };
  else               t = { kind: 'boot', e: '👢', p: 0, good: false };
  let vy = 2 + Math.random() * 1.5 + level * 0.05;
  if (t.kind === 'gold') vy += 1.5;
  items.push({ ...t, x: 30 + Math.random() * (W - 60), y: -30, vy });
}

function popup(x, y, txt, color) { popups.push({ x, y, txt, color, life: 50 }); }

function update(dt) {
  tick += dt;
  if (state !== 'play') return;
  if (keys['ArrowLeft'] || keys['a']) { cat.x -= 8 * dt; cat.facing = -1; targetX = null; }
  if (keys['ArrowRight'] || keys['d']) { cat.x += 8 * dt; cat.facing = 1; targetX = null; }
  if (targetX !== null) {
    const dx = targetX - cat.x;
    if (Math.abs(dx) > 2) cat.facing = dx > 0 ? 1 : -1;
    cat.x += dx * Math.min(1, 0.25 * dt);
  }
  cat.x = Math.max(35, Math.min(W - 35, cat.x));

  timer -= dt;
  if (timer <= 0) { spawn(); timer = Math.max(25, 65 - Math.min(score, 40) * 1.0); }

  for (let i = items.length - 1; i >= 0; i--) {
    const it = items[i];
    it.y += it.vy * dt;
    if (Math.abs(it.x - cat.x) < 45 && it.y > cat.y - 45 && it.y < cat.y + 10) {
      if (it.kind === 'gold') { score += 100; popup(it.x, it.y, '+100 GOLDEN!', '#d99a00'); }
      else if (it.good) { score += it.p; popup(it.x, it.y, '+' + it.p, '#1e8e3e'); }
      else { lives--; popup(it.x, it.y, 'Ew, a boot!', '#d93025'); }
      items.splice(i, 1);
    } else if (it.y > H - 20) {
      if (it.good && !it.free) { lives--; popup(it.x, H - 50, 'Missed!', '#d93025'); }
      items.splice(i, 1);
    }
  }
  popups.forEach(p => { p.y -= 0.8 * dt; p.life -= dt; });
  popups = popups.filter(p => p.life > 0);

  if (lives <= 0) { state = 'over'; best = Math.max(best, score); }
}

function text(s, x, y, size, color, align = 'center') {
  ctx.font = `bold ${size}px system-ui, sans-serif`;
  ctx.textAlign = align; ctx.textBaseline = 'middle';
  ctx.fillStyle = color;
  ctx.fillText(s, x, y);
}

function emoji(e, x, y, size) {
  ctx.font = size + 'px serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(e, x, y);
}

function ell(x, y, rx, ry, color) {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2); ctx.fill();
}

function tri(x1, y1, x2, y2, x3, y3, color) {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.lineTo(x3, y3);
  ctx.closePath(); ctx.fill();
}

function line(x1, y1, x2, y2, color, w) {
  ctx.strokeStyle = color; ctx.lineWidth = w; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
}

