Here's a complete game in a single file. Save it as `cat-game.html` and open it in any browser (works on phones too).

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Catch the Fish!</title>
<style>
  body { margin:0; background:#1b2a49; display:flex; justify-content:center;
         align-items:center; height:100vh; overflow:hidden; }
  canvas { background:linear-gradient(#87ceeb,#e0f6ff); max-width:100%;
           max-height:100%; touch-action:none; }
</style>
</head>
<body>
<canvas id="c" width="480" height="640"></canvas>
<script>
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");
const W = canvas.width, H = canvas.height;

let state = "start";            // start | play | over
let cat, fish, score, lives, spawnTimer, best = +localStorage.getItem("catBest") || 0;
const keys = {};

function reset() {
  cat = { x: W/2, y: H - 70, speed: 420 };
  fish = [];
  score = 0;
  lives = 3;
  spawnTimer = 0.5;
  state = "play";
}

function spawn() {
  const r = Math.random();
  let type = "normal";
  if (r < 0.10) type = "golden";
  else if (r < 0.22 + Math.min(score * 0.002, 0.1)) type = "puffer";
  fish.push({
    x: 30 + Math.random() * (W - 60),
    y: -30,
    vy: Math.min(130 + score * 3 + Math.random() * 60, 420),
    type,
    wobble: Math.random() * Math.PI * 2
  });
}

function update(dt) {
  if (state !== "play") return;

  if (keys["ArrowLeft"] || keys["a"]) cat.x -= cat.speed * dt;
  if (keys["ArrowRight"] || keys["d"]) cat.x += cat.speed * dt;
  cat.x = Math.max(35, Math.min(W - 35, cat.x));

  spawnTimer -= dt;
  if (spawnTimer <= 0) {
    spawn();
    spawnTimer = Math.max(0.35, 1 - score * 0.012);
  }

  for (const f of fish) {
    f.y += f.vy * dt;
    f.wobble += dt * 4;
    f.x += Math.sin(f.wobble) * 20 * dt;
  }

  for (let i = fish.length - 1; i >= 0; i--) {
    const f = fish[i];
    const caught = f.y > cat.y - 25 && f.y < cat.y + 30 && Math.abs(f.x - cat.x) < 45;
    if (caught) {
      if (f.type === "normal") score += 1;
      else if (f.type === "golden") score += 5;
      else lives--;                       // ouch, pufferfish!
      fish.splice(i, 1);
    } else if (f.y > H + 20) {
      if (f.type !== "puffer") lives--;   // missed a good fish
      fish.splice(i, 1);
    }
  }

  if (lives <= 0) {
    state = "over";
    if (score > best) { best = score; localStorage.setItem("catBest", best); }
  }
}

function text(str, x, y, size, color = "#222") {
  ctx.fillStyle = color;
  ctx.font = `bold ${size}px sans-serif`;
  ctx.textAlign = "center";
  ctx.fillText(str, x, y);
}

function emoji(e, x, y, size) {
  ctx.font = `${size}px serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(e, x, y);
  ctx.textBaseline = "alphabetic";
}

function draw() {
  ctx.clearRect(0, 0, W, H);

  // ground
  ctx.fillStyle = "#7ec850";
  ctx.fillRect(0, H - 35, W, 35);

  if (state === "start") {
    emoji("🐱", W/2, 220, 100);
    text("Catch the Fish!", W/2, 330, 40);
    text("Move: arrow keys / A D / drag", W/2, 380, 20, "#444");
    text("🐟 +1   🐠 +5   🐡 = ouch!", W/2, 415, 22, "#444");
    text("Tap or press Space to start", W/2, 480, 24, "#d2552b");
    text("Best: " + best, W/2, 520, 20, "#444");
    return;
  }

  for (const f of fish) {
    const e = f.type === "normal" ? "🐟" : f.type === "golden" ? "🐠" : "🐡";
    emoji(e, f.x, f.y, 40);
  }
  emoji("🐱", cat.x, cat.y, 64);

  text("Score: " + score, 80, 35, 24);
  text("Best: " + best, W/2, 35, 20, "#555");
  text("❤️".repeat(Math.max(lives, 0)), W - 70, 35, 22);

  if (state === "over") {
    ctx.fillStyle = "rgba(0,0,0,0.55)";
    ctx.fillRect(0, 0, W, H);
    text("Game Over", W/2, 250, 48, "#fff");
    text("Score: " + score, W/2, 305, 30, "#fff");
    if (score >= best && score > 0) text("New best! 🎉", W/2, 345, 24, "#ffd54a");
    text("Tap or press Space to play again", W/2, 420, 22, "#fff");
  }
}

let last = performance.now();
function loop(now) {
  const dt = Math.min((now - last) / 1000, 0.05);
  last = now;
  update(dt);
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

// Input
addEventListener("keydown", e => {
  keys[e.key] = true;
  if ((e.key === " " || e.key === "Enter") && state !== "play") reset();
  if (e.key.startsWith("Arrow") || e.key === " ") e.preventDefault();
});
addEventListener("keyup", e => keys[e.key] = false);

function pointerX(e) {
  const rect = canvas.getBoundingClientRect();
  return (e.clientX - rect.left) * (W / rect.width);
}
canvas.addEventListener("pointerdown", e => {
  if (state !== "play") { reset(); return; }
  cat.x = pointerX(e);
});
canvas.addEventListener("pointermove", e => {
  if (state === "play" && (e.buttons || e.pointerType === "mouse")) cat.x = pointerX(e);
});
</script>
</body>
</html>
