  for (const it of items) {
    it.y += it.vy * dt;
    it.a += it.spin * dt * 3;
    const caught = Math.abs(it.x - cat.x) < 40 && it.y > cat.y - 35 && it.y < cat.y + 15;
    if (caught) {
      it.dead = true;
      if (it.type === 'fish')      { score += 1; pop(it.x, it.y, '+1', '#1a7f37'); }
      else if (it.type === 'gold') { score += 5; pop(it.x, it.y, '+5!', '#c78a00'); }
      else                         { pop(it.x, it.y, 'Ew, a boot!', '#c0392b'); loseLife(); }
    } else if (it.y > H + 20) {
      it.dead = true;
      if (it.type !== 'boot') { pop(it.x, H - 30, 'Missed!', '#c0392b'); loseLife(); }
    }
  }
  items = items.filter(i => !i.dead);

  for (const p of pops) { p.y -= 40 * dt; p.life -= dt; }
  pops = pops.filter(p => p.life > 0);
}

function text(t, x, y, size, color = '#1b2a49') {
  ctx.fillStyle = color;
  ctx.font = `bold ${size}px sans-serif`;
  ctx.textAlign = 'center';
  ctx.fillText(t, x, y);
}

function draw() {
  ctx.clearRect(0, 0, W, H);

  // ground
  ctx.fillStyle = '#8bd36b';
  ctx.fillRect(0, H - 25, W, 25);

  // items
  ctx.textBaseline = 'middle';
  for (const it of items) {
    ctx.save();
    ctx.translate(it.x, it.y);
    ctx.rotate(it.a * 0.3);
    ctx.font = '38px serif';
    ctx.textAlign = 'center';
    ctx.fillText(it.emoji, 0, 0);
    ctx.restore();
  }

  // cat
  ctx.font = '64px serif';
  ctx.textAlign = 'center';
  ctx.fillText('🐱', cat.x, cat.y);

  // floating text
  for (const p of pops) {
    ctx.globalAlpha = Math.max(0, p.life / 0.8);
    text(p.text, p.x, p.y, 20, p.color);
  }
  ctx.globalAlpha = 1;

  ctx.textBaseline = 'alphabetic';
  // HUD
  ctx.textAlign = 'left';
  ctx.fillStyle = '#1b2a49';
  ctx.font = 'bold 22px sans-serif';
  ctx.fillText('Score: ' + score, 14, 32);
  ctx.textAlign = 'right';
  ctx.fillText('❤️'.repeat(Math.max(0, lives)), W - 14, 32);
  ctx.textAlign = 'left';
  ctx.font = '14px sans-serif';
  ctx.fillText('Best: ' + best, 14, 54);

  if (state === 'start') {
    overlay();
    text('🐱 Catch the Fish! 🐟', W/2, 240, 32);
    text('Move: mouse, touch, or ← → / A D', W/2, 300, 18);
    text('🐟 +1   🐠 +5   👢 avoid!', W/2, 335, 20);
    text('Don\'t let fish hit the ground', W/2, 370, 18);
    text('Click or press Space to start', W/2, 430, 22, '#c0392b');
  } else if (state === 'over') {
    overlay();
    text('Game Over', W/2, 260, 40);
    text('Score: ' + score, W/2, 310, 26);
    text('Best: ' + best, W/2, 345, 20);
    text('Click or press Space to play again', W/2, 410, 20, '#c0392b');
  }
}

function overlay() {
  ctx.fillStyle = 'rgba(255,255,255,0.75)';
  ctx.fillRect(40, 170, W - 80, 300);
}

let last = performance.now();
function loop(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  update(dt);
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
</script>
</body>
</html>
```

**Controls:** move your mouse (or finger on a touchscreen) or use the arrow keys to slide the cat. Catch 🐟 for 1 point and 🐠 for 5 points, and dodge the 👢 boots. You have 3 lives!

